answers.workaround:
This can be worked around using what [u/mrcdk helped me create on the Godot Forums,](https://forum.godotengine.org/t/how-to-set-member-function-colour-inside-codehighlighter/106329) using a custom class which gets the default data from a duplicate CodeEdit held inside the class, reads and modifies that returned data before returning it to the real CodeEdit;

```
func _init() -> void:  
	self.resource_local_to_scene = true
	text_holder = CodeEdit.new()
	var highlighter : CodeHighlighter = CodeHighlighter.new()
	highlighter.resource_local_to_scene = true
	highlighter.number_color = highlight_num_colour
	highlighter.symbol_color = highlight_sym_colour
	highlighter.function_color = highlight_func_colour
	highlighter.member_variable_color = highlight_mvar_colour
	highlighter.keyword_colors = highlight_keywords
	highlighter.color_regions = highlight_regions
	text_holder.syntax_highlighter = highlighter

func _get_line_syntax_highlighting(line: int) -> Dictionary:
	var editor : CodeEdit = get_text_edit()
	text_holder.text = editor.text
	if editor.get_line(line).begins_with("func") or editor.get_line(line).begins_with("static func"):
		var line_highlight_data : Dictionary = text_holder.syntax_highlighter.get_line_syntax_highlighting(line)
		for key : int in line_highlight_data.keys():
			if line_highlight_data[key]["color"] == highlight_func_colour:
				line_highlight_data[key]["color"] = highlight_def_func_colour
		return line_highlight_data
	return text_holder.syntax_highlighter.get_line_syntax_highlighting(line)
```
